    "hs.region.kakum": "المنطقة الوسطى — ممر ظُلّة الغابة",
    "hs.region.capecoast": "المنطقة الوسطى — ساحل الأطلسي",
    "hs.region.elmina": "المنطقة الوسطى — ساحل الأطلسي",
    "hs.region.monument": "أكرا — أكرا الكبرى",
    "hs.region.volta": "المنطقة الشرقية — أكبر خزان مائي في العالم",
