    "hs.region.kakum": "Zentralregion — Baumkronenpfad",
    "hs.region.capecoast": "Zentralregion — Atlantikküste",
    "hs.region.elmina": "Zentralregion — Atlantikküste",
    "hs.region.monument": "Accra — Greater Accra",
