    "hs.region.kakum": "Mkoa wa Kati — Daraja la Vilele vya Miti",
    "hs.region.capecoast": "Mkoa wa Kati — Pwani ya Atlantiki",
    "hs.region.elmina": "Mkoa wa Kati — Pwani ya Atlantiki",
    "hs.region.monument": "Accra — Accra Kuu",
    "hs.region.volta": "Mkoa wa Mashariki — Hifadhi Kubwa Zaidi ya Maji Duniani",
