    "hs.region.kakum": "Yankin Tsakiya — Gadar Saman Bishiyoyi",
    "hs.region.capecoast": "Yankin Tsakiya — Gabar Tekun Atlantika",
    "hs.region.elmina": "Yankin Tsakiya — Gabar Tekun Atlantika",
    "hs.region.monument": "Accra — Babban Accra",
    "hs.region.volta": "Yankin Gabas — Tafki Mafi Girma a Duniya",
    "hs.region.wli": "Yankin Volta — Tsaunukan Agumatsa",
